import React, { ChangeEvent, FC } from 'react';
import MenuItem from '@mui/material/MenuItem';
import { FormControl, FormHelperText, InputLabel, Select } from '@mui/material';

import { IListInput, IListValue } from '../types';

import InputRoot from './InputRoot';

const ListInput: FC<IListInput> = (props) => {
  const { id, value, values, caption, tooltip = '', size = 'small', disabled = false, onChange } = props;

  const handleChange = (e: ChangeEvent<HTMLInputElement>): void => {
    if (onChange) {
      const val = e?.target?.value;
      onChange(val);
    }
  };

  return (
    <InputRoot size={size}>
      <FormControl size={'medium'} sx={{ minWidth: 235, maxHeight: 51 }}>
        <InputLabel id={`${id}-label`}>{caption}</InputLabel>
        <Select variant="outlined" label={caption} labelId={`${id}-label`} id={id} value={value} disabled={disabled} onChange={handleChange}>
          {values.map((item: IListValue) => (
            <MenuItem key={item.value} value={item.value}>
              {item.text}
            </MenuItem>
          ))}
        </Select>
        {tooltip && <FormHelperText>{tooltip}</FormHelperText>}
      </FormControl>
    </InputRoot>
  );
};

export default ListInput;
