export const wait = async (delay: number, callback: () => void): Promise<number> =>
  await new Promise((resolve) => resolve(window.setTimeout(callback, delay)));

export const getSize = (val: string | undefined): string => {
  switch (val) {
    case 'xSmall':
      return '150px';
    case 'small':
      return '300px';
    case 'half':
      return '50%';
    case 'big':
      return '75%';
    case 'fill':
      return '100%';
    default:
      return '150px';
  }
};
