import {
  SETTINGS_BOOLEAN_DATA_CHANGED,
  SETTINGS_GET_OPTIONS,
  SETTINGS_GET_SETTINGS,
  SETTINGS_INTEGER_DATA_CHANGED,
  SETTINGS_SAVE_SETTINGS,
  SETTINGS_SET_SETTINGS,
  SETTINGS_STRING_DATA_CHANGED,
  SETTINGS_SET_SETTINGS_STATE,
  ERROR,
  START,
  STOP,
  SUCCESS,
} from '../../constants';
import type { TAction, TOptions, TSettings } from '../../../../types/admin';
import { ISettingsState } from '../../../../types/state';

const initialState: ISettingsState = {
  settings: {
    themeName: 'stb-dark',
    roundedCorners: true,
    radius: 5,
    borderStyle: 'solid',
    borderWidth: 1,
    margins: {
      top: 20,
      left: 10,
      right: 10,
      bottom: 20,
    },
    bigImg: true,
    showImg: true,
    collapsing: true,
    collapsed: false,
    langDirect: 'ltr',
    mode: 'css',
    side: 0,
    imgMinus: {
      image: '',
      defaultImage:
        'data:image/png;base64,',
      enabled: false,
    },
    imgPlus: {
      image: '',
      defaultImage:
        'data:image/png;base64,',
      enabled: false,
    },
    duration: 500,
    caption: {
      font: {
        fontSize: 12,
        fontFamily: 'Impact, Verdana, Helvetica, Arial, sans-serif',
      },
    },
    shadow: {
      enabled: true,
      inset: false,
      offsetX: 0,
      offsetY: 0,
      blur: 15,
      alpha: 0.15,
      color: '#555555',
    },
    text: {
      shadow: {
        enabled: false,
        offsetX: 1,
        offsetY: 1,
        blur: 3,
        alpha: 0.15,
        color: '#000000',
      },
      font: {
        fontSize: 0,
        fontFamily: 'Impact, Verdana, Helvetica, Arial, sans-serif',
      },
      height: 'inherit',
      customHeight: 0,
    },
    deleteOptions: 0,
    deleteDB: 0,
    cssLoading: 'dynamic',
  },
  options: {
    restData: null,
    texts: null,
    media: {
      title: '',
      button: '',
    },
    pluginData: {
      root: '',
    },
  },
  loading: false,
  saving: false,
  savingSuccess: false,
  savingError: false,
};

const reducer = (state: ISettingsState = initialState, action: TAction): ISettingsState => {
  switch (action.type) {
    case SETTINGS_INTEGER_DATA_CHANGED: {
      return state;
    }

    case SETTINGS_STRING_DATA_CHANGED: {
      return state;
    }

    case SETTINGS_BOOLEAN_DATA_CHANGED: {
      return state;
    }

    case SETTINGS_SET_SETTINGS_STATE:
      return { ...state, ...(action.payload as Record<string, unknown>) };

    case SETTINGS_SET_SETTINGS:
      return { ...state, settings: { ...state.settings, ...(action.payload as Record<string, unknown>) } };

    case SETTINGS_GET_SETTINGS + START:
      return { ...state, loading: true };

    case SETTINGS_GET_SETTINGS + SUCCESS:
      return { ...state, settings: { ...(action.payload as TSettings) }, loading: false };

    case SETTINGS_GET_SETTINGS + ERROR:
      return { ...state, loading: false };

    case SETTINGS_SAVE_SETTINGS + START:
      return { ...state, saving: true };

    case SETTINGS_SAVE_SETTINGS + SUCCESS:
      return { ...state, saving: false, savingSuccess: true, savingError: false };

    case SETTINGS_SAVE_SETTINGS + ERROR:
      return { ...state, saving: false, savingSuccess: false, savingError: true };

    case SETTINGS_SAVE_SETTINGS + STOP:
      return { ...state, saving: false, savingSuccess: false, savingError: false };

    case SETTINGS_GET_OPTIONS:
      return { ...state, options: action.payload as TOptions };

    default:
      return state;
  }
};

export default reducer;
